def _ge(ind_reason, tail, newread):
    # old: the guard's read line + the closing of the guard + the first line after it (the unique tail)
    base=ind_reason+"@@READ@@\n"
    return None
def _edit(indent, oldread, newread, tail):
    s=' '*indent
    o=s+"reason = %s;\n"%oldread+(s[:-2])+"} catch {\n"+s+"reason = 'unreadable thrown value';\n"+(s[:-2])+"}\n"+tail
    n=o.replace("reason = %s;"%oldread,"reason = %s;"%newread,1)
    return (o,n)
